-- Inert Run07: preserves archived state and requires reviewed content before revival.
create table if not exists public.audn_idea_revival_guards (
 idea_id uuid primary key, corrected_fields jsonb not null, reviewed_at timestamptz not null default now()
);
alter table public.audn_idea_revival_guards enable row level security;
revoke all on public.audn_idea_revival_guards from public,anon,authenticated;
grant select,insert,update on public.audn_idea_revival_guards to service_role;
insert into public.audn_idea_revival_guards(idea_id,corrected_fields) values
('aac30b97-940b-4e95-a5ec-86607e37a414','{"raw_topic": "What your own post history can tell you about useful subjects", "normalized_topic": "What your own post history can tell you about useful subjects", "post_angle": "Use an external category study as a question to investigate. Compare the client’s own posts at a common observation age, with separate metrics and visible sample sizes. Subject, format and commercial outcomes are different measurements.", "raw_context": "{\"correction_version\": \"imagine07-v1\", \"correction_reason\": \"Descriptive third-party category averages do not prove certain subjects are universally weakest or cause underperformance.\", \"original_audit\": {\"raw_context\": \"Mechanism: the categories that need a visible person (story, milestone, hiring) outperform the ones that can be produced without one (industry insight, event, product update) by 2.5 to 3.4x, and the market ships the easy ones 62% of the time. Third-party study of B2B software companies, not agencies; cite as Imagine AI''s index. Reader move: audit own last 20 posts by category. (NEEDS IVAN''S REAL DATA: same category split on Ivan''s own feed or a client feed, if he wants a first-person receipt.)\", \"evidence\": [{\"who\": \"Imagine AI (useimagine.ai), B2B Index of 101 B2B software companies\", \"tier\": \"FACT\", \"quote\": \"The three most common categories - Industry Insight (22.4% of all posts), Event (21.2%), Product Update (18.7%) - are the three weakest performers, earning 48, 61, and 74 average engagement respectively. The three strongest - Celebratory Announcements (162), Personal Stories (127), Hiring posts (122) - together make up under 22% of what gets posted.\", \"source\": \"claude_sessions\", \"instrument\": \"Imagine AI B2B Index, 32,277 original posts by 744 executives, vision-language category classifier, smart (5%-trimmed) averages, snapshot Aug 2026, published at useimagine.ai/blog/what-b2b-actually-posts and benchmark.imagineai.me\"}], \"editorial_assessment\": \"This is for the agency owner or their content lead who publishes industry commentary weekly and cannot understand why it goes nowhere. The data is genuinely good, 32,277 posts showing the three most-published categories are the three worst performers while personal stories pull 127 against industry insight''s 48, and that inversion is the whole post. The risk is it reads as third-party benchmark trivia, so Ivan should pin it to what agencies specifically do, publish safe insight posts because they feel professional, and the volume-versus-return contrast is the one thing here that earns a visual card.\", \"angle_options\": [{\"key\": \"a1\", \"angle\": \"Imagine AI just scanned 32,277 posts from 744 B2B executives and found the three most common post types are also the three weakest performers. Industry Insight posts, 22% of everything published, average 48 engagements. Event posts, 21%, average 61. Product Updates, 19%, average 74. Three out of every five posts on B2B LinkedIn are built to underperform, and almost nobody posting them knows it.\", \"label\": \"62% of B2B posts flop by design\", \"awareness_stage\": \"problem_unaware\"}, {\"key\": \"a2\", \"angle\": \"A 32,277-post study of B2B executives found Celebratory Announcements, Personal Stories, and Hiring posts pull 122 to 162 average engagements each, while Industry Insight, Event, and Product Update posts, the three formats that make up nearly 80% of everything B2B companies publish, pull 48 to 74. Every dollar an agency spends producing ''safe'' industry content is a dollar spent shrinking its own reach.\", \"label\": \"You''re paying to be ignored\", \"awareness_stage\": \"pain_aware\"}, {\"key\": \"a3\", \"angle\": \"Imagine AI ran a classifier over 32,277 LinkedIn posts from 744 executives and found the highest-performing formats, Celebratory Announcements, Personal Stories, Hiring posts, make up under 22% of what B2B companies actually post. Everyone chasing ''thought leadership'' is fighting over the same three exhausted formats while the highest-return content sits almost untouched.\", \"label\": \"The 22% nobody bothers posting\", \"awareness_stage\": \"solution_aware\"}]}, \"revival_requires\": \"This exact correction must be applied before any archived-to-active transition.\"}", "editorial_assessment": "Descriptive third-party category averages do not prove certain subjects are universally weakest or cause underperformance.", "angle_options": [{"key": "corrected-v1", "label": "What your own post history can tell you about useful subjects", "angle": "Use an external category study as a question to investigate. Compare the client’s own posts at a common observation age, with separate metrics and visible sample sizes. Subject, format and commercial outcomes are different measurements.", "awareness_stage": "pain_aware"}], "evidence": [{"tier": "EDITORIAL_CORRECTION", "source": "imagine-ai-07", "instrument": "Captured source review at 2026-09-13T16:57:16.263080+00:00", "quote": "Descriptive third-party category averages do not prove certain subjects are universally weakest or cause underperformance."}]}'::jsonb),
('d21eeb79-3d78-47b6-a14a-16211d7f43b7','{"raw_topic": "Choose media that makes the point verifiable", "normalized_topic": "Choose media that makes the point verifiable", "post_angle": "Use a screen recording when the viewer needs to see a process, a document when they need a sequence, and a photo when it supplies relevant evidence. The cited media averages do not compare real media against AI or stock images and do not establish causal lift.", "raw_context": "{\"correction_version\": \"imagine07-v1\", \"correction_reason\": \"Remove fabricated real/AI comparison, algorithm claims and universal doubling promise.\", \"original_audit\": {\"raw_context\": \"Mechanism: media roughly doubles engagement; the ''real'' qualifier is Imagine AI''s stated observation of the top posts, not a measured split between real and AI images (flag as OBSERVATION if quoted). Third-party B2B software index. (NEEDS IVAN''S REAL DATA: media vs text split on Ivan''s own feed.)\", \"evidence\": [{\"who\": \"Imagine AI (useimagine.ai), B2B Index of 101 B2B software companies\", \"tier\": \"FACT\", \"quote\": \"Video posts average 108.5 engagements, image posts 93.7, other formats 50, and text-only posts 49 ... the top-performing posts in the Index use authentic photos and footage - launch films, team photos, screen recordings - not stock or AI-generated images.\", \"source\": \"claude_sessions\", \"instrument\": \"Imagine AI B2B Index, 32,277 original posts, smart average by media format, snapshot Aug 2026; useimagine.ai/blog/what-b2b-actually-posts\"}], \"editorial_assessment\": \"This speaks to the agency owner who is posting on LinkedIn to build inbound and quietly outsourcing their visuals to an AI image generator because it is faster. The finding that lands is not the engagement multiple, it is the second half: the top performers used launch films, team photos and screen recordings, and the polished synthetic stuff loses. Treat it as a directional post about proof of existence rather than a stat post, since the numbers are third-party and unremarkable on their own, and Ivan has no build of his own attached to it.\", \"angle_options\": [{\"key\": \"a1\", \"angle\": \"Imagine AI just pulled data from 32,277 B2B LinkedIn posts and found the top performers all skip stock photos and AI-generated images entirely. Video and real screen recordings pull 108.5 engagements on average versus 93.7 for images and 49 for plain text, according to the report. Every founder who swapped a real screen recording for a slick AI thumbnail to save an hour just traded engagement for convenience and never noticed the trade.\", \"label\": \"Your AI thumbnails are killing reach\", \"awareness_stage\": \"problem_unaware\"}, {\"key\": \"a2\", \"angle\": \"One format doubles engagement on LinkedIn and most agency founders never touch it. Across 32,277 B2B posts, video and screen recordings averaged 108.5 engagements while text-only posts scraped by on 49, according to Imagine AI''s B2B Index. If you''re paying for reach with AI-generated carousels instead of filming your own screen, you''re buying the exact content type the algorithm engages with least.\", \"label\": \"The post format starving your pipeline\", \"awareness_stage\": \"pain_aware\"}, {\"key\": \"a3\", \"angle\": \"Every agency is racing to generate slicker AI images for LinkedIn while the data says the opposite move wins. Imagine AI''s analysis of 32,277 B2B posts found the highest-performing content used raw launch films, team photos, and screen recordings instead of stock or AI-generated visuals. The founders spending hours in Midjourney and Gemini polishing thumbnails are optimizing for the exact format LinkedIn engages with least.\", \"label\": \"AI images lose to a screen recording\", \"awareness_stage\": \"solution_aware\"}]}, \"revival_requires\": \"This exact correction must be applied before any archived-to-active transition.\"}", "editorial_assessment": "Remove fabricated real/AI comparison, algorithm claims and universal doubling promise.", "angle_options": [{"key": "corrected-v1", "label": "Choose media that makes the point verifiable", "angle": "Use a screen recording when the viewer needs to see a process, a document when they need a sequence, and a photo when it supplies relevant evidence. The cited media averages do not compare real media against AI or stock images and do not establish causal lift.", "awareness_stage": "pain_aware"}], "evidence": [{"tier": "EDITORIAL_CORRECTION", "source": "imagine-ai-07", "instrument": "Captured source review at 2026-09-13T16:57:16.263080+00:00", "quote": "Remove fabricated real/AI comparison, algorithm claims and universal doubling promise."}]}'::jsonb)
on conflict(idea_id) do nothing;
create or replace function public.audn_guard_idea_revival()
returns trigger language plpgsql security definer set search_path=public as $$
declare expected jsonb;
begin
 if old.status='archived' and new.status is distinct from 'archived' then
  select corrected_fields into expected from audn_idea_revival_guards where idea_id=old.id;
  if found and not(to_jsonb(new) @> expected) then
   raise exception 'audn_correction_required_before_revival';
  end if;
 end if;
 return new;
end;
$$;
drop trigger if exists audn_idea_revival_guard on public.lm_idea_candidates;
create trigger audn_idea_revival_guard before update on public.lm_idea_candidates
for each row execute function public.audn_guard_idea_revival();
